<script setup lang="ts">
import {ref,computed} from 'vue';import type {EChartsOption} from 'echarts';import {IconRefresh} from '@arco-design/web-vue/es/icon';
import PageHeader from '../components/PageHeader.vue';import StatChart from '../components/StatChart.vue';import {api} from '../api/console';import {useResource} from '../composables/useResource';
const days=ref(7);const {data,loading,error,refresh}=useResource(()=>api.dashboard(days.value));void refresh();
const cards=[['newUsers','今日新增用户','账号注册'],['dau','今日活跃 / DAU','匿名安装设备'],['mau','月活跃 / MAU','最近 30 天设备'],['bookkeeping','今日新增流水','已上报保存事件'],['autoSaved','自动记账成功数','事件链已写库'],['autoSuccessRate','自动记账成功率','候选 → 写库'],['aiCalls','AI 识别次数','等待 usage 接入'],['aiSuccessRate','AI 识别成功率','等待调用回执'],['backupSuccessRate','云备份成功率','等待任务遥测'],['errors','今日错误数量','已接入诊断'],['latestVersion','Android 最新版','全量发布版本'],['totalUsers','累计用户','未注销账号']];
function metric(key:string){const value=data.value?.metrics[key];if(value==null)return '—';return key.endsWith('Rate')?(Number(value)*100).toFixed(1)+'%':typeof value==='number'?value.toLocaleString('zh-CN'):value;}
const trend=computed<EChartsOption>(()=>({animation:false,color:['#42695a','#8a98b4','#d29955'],tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:40,right:18,top:20,bottom:55},xAxis:{type:'category',data:data.value?.trends.map(r=>r.day.slice(5))??[]},yAxis:{type:'value',minInterval:1,splitLine:{lineStyle:{color:'#eef0f3'}}},series:[{name:'活跃设备',type:'line',smooth:true,data:data.value?.trends.map(r=>r.active)},{name:'记账次数',type:'line',smooth:true,data:data.value?.trends.map(r=>r.bookkeeping)},{name:'新增用户',type:'bar',barMaxWidth:16,data:data.value?.trends.map(r=>r.users)}]}));
const versions=computed<EChartsOption>(()=>({animation:false,color:['#42695a','#799888','#acbdb3','#d4ded8'],tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['45%','70%'],center:['50%','42%'],label:{show:false},data:data.value?.versions??[]}]}));
const sources=computed<EChartsOption>(()=>({animation:false,color:['#42695a'],tooltip:{trigger:'axis'},grid:{left:150,right:20,top:10,bottom:30},xAxis:{type:'value',minInterval:1},yAxis:{type:'category',data:data.value?.sources.map(r=>r.name)},series:[{type:'bar',barMaxWidth:18,data:data.value?.sources.map(r=>r.value)}]}));
</script>
<template><page-header title="工作台" description="了解产品运行情况，定位需要关注的问题。"><a-radio-group v-model="days" type="button" @change="refresh"><a-radio :value="7">最近 7 天</a-radio><a-radio :value="30">最近 30 天</a-radio></a-radio-group><a-button @click="refresh"><template #icon><icon-refresh/></template>刷新</a-button></page-header><a-alert v-if="error" type="error">{{ error }}<template #action><a-button @click="refresh">重试</a-button></template></a-alert><div class="metrics-grid"><article v-for="card in cards" :key="card[0]" class="surface metric"><p>{{ card[1] }}</p><a-skeleton v-if="loading" animation><a-skeleton-line :rows="1"/></a-skeleton><strong v-else>{{ metric(card[0]??'') }}</strong><span>{{ card[2] }}</span></article></div><section class="surface chart-panel"><div class="section-heading"><h2>用户与记账趋势</h2><span class="muted">Asia/Shanghai · 按日汇总</span></div><a-spin :loading="loading" class="block"><stat-chart v-if="data" :option="trend" label="用户与记账趋势图"/><a-empty v-else description="暂无统计数据"/></a-spin></section><div class="two-columns"><section class="surface chart-panel"><h2>APP 版本分布</h2><a-spin :loading="loading" class="block"><stat-chart v-if="data?.versions.length" :option="versions" label="APP 版本分布"/><a-empty v-else description="尚未收到设备版本上报"/></a-spin></section><section class="surface chart-panel"><h2>支付来源分布</h2><a-spin :loading="loading" class="block"><stat-chart v-if="data?.sources.length" :option="sources" label="支付来源分布"/><a-empty v-else description="尚未收到自动记账事件"/></a-spin></section></div><a-collapse v-if="data" class="integration-note"><a-collapse-item header="数据接入状态与统计口径" key="integration"><p v-for="(message,key) in data.integration" :key="key">{{ message }}</p><p>“—”表示数据尚不可计算，0 表示对应数据源当前没有记录。DAU / MAU 按匿名安装设备去重。</p></a-collapse-item></a-collapse></template>
